dataprocessscript.script:
import java.util.Properties;
import java.io.InputStream;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.nio.file.AtomicMoveNotSupportedException;

for (int i = 0; i < dataContext.getDataCount(); i++) {
    InputStream is = dataContext.getStream(i);
    Properties props = dataContext.getProperties(i);
    is.close();

    File processingDir = new File("D:\\BoomiLab\\Project01\\work\\processing");
    File readyDir = new File("D:\\BoomiLab\\Project01\\work\\ready");
    File committedDir = new File("D:\\BoomiLab\\Project01\\work\\committed");
    processingDir.mkdirs(); readyDir.mkdirs(); committedDir.mkdirs();
    int inspected = 0; int restored = 0; int preserved = 0;
    long now = System.currentTimeMillis();

    File[] files = processingDir.listFiles();
    if (files != null) {
        for (File f : files) {
            if (!f.isFile() || !f.getName().endsWith(".processing.json")) continue;
            inspected++;
            String base = f.getName().substring(0, f.getName().length() - 16);
            File committed = new File(committedDir, base + ".committed.json");
            File ready = new File(readyDir, base + ".ready.json");
            if (committed.exists()) { preserved++; continue; }
            if ((now - f.lastModified()) <= 1800000L) { preserved++; continue; }
            if (ready.exists()) { preserved++; continue; }
            try { Files.move(f.toPath(), ready.toPath(), StandardCopyOption.ATOMIC_MOVE); }
            catch (AtomicMoveNotSupportedException ex) { Files.move(f.toPath(), ready.toPath()); }
            restored++;
        }
    }

    String json = "{\"inspected\":" + inspected + ",\"restoredToReady\":" + restored + ",\"preserved\":" + preserved + "}";
    dataContext.storeStream(new ByteArrayInputStream(json.getBytes("UTF-8")), props);
}
